#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
constexpr int MAXN = 15;
constexpr int MAXT = 65;

struct Edge {
    int to, cap, rev;
};

class Dinic {
private:
    int n, S, T;
    vector<vector<Edge>> g;
    vector<int> level, it;
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(S);
        level[S] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const Edge &e : g[u]) {
                if (level[e.to] == -1 && e.cap > 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[T] != -1;
    }
    int dfs(int u, int f) {
        if (u == T) return f;
        for (int &i = it[u]; i < (int)g[u].size(); ++i) {
            Edge &e = g[u][i];
            if (level[e.to] == level[u] + 1 && e.cap > 0) {
                int pushed = dfs(e.to, min(f, e.cap));
                if (pushed != 0) {
                    e.cap -= pushed;
                    g[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }
public:
    Dinic(int n, int s, int t) : n(n), S(s), T(t), g(n), level(n), it(n) {}
    void add_edge(int u, int v, int cap) {
        g[u].push_back({v, cap, (int)g[v].size()});
        g[v].push_back({u, 0, (int)g[u].size() - 1});
    }
    ll max_flow() {
        ll ret = 0;
        while (bfs()) {
            fill(it.begin(), it.end(), 0);
            while (int add = dfs(S, 2e9)) ret += add;
        }
        return ret;
    }
};

int n, tim;
string board[15], target[15];
int dist[15][15];
int id[15][15][65];
int start_r, start_c;
const int dr[4] = {-1, 1, 0, 0};
const int dc[4] = {0, 0, -1, 1};

void make_dist() {
    queue<pair<int,int>> q;
    q.push({start_r, start_c});
    dist[start_r][start_c] = 1;
    int cur = 1;
    while (!q.empty()) {
        int s = (int)q.size();
        for (int i = 0; i < s; ++i) {
            pair<int,int> p = q.front(); q.pop();
            for (int d = 0; d < 4; ++d) {
                int nr = p.first + dr[d];
                int nc = p.second + dc[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
                if (dist[nr][nc] || board[nr][nc] == 'Y') continue;
                dist[nr][nc] = cur;
                q.push({nr, nc});
            }
        }
        ++cur;
        cur = min(cur, tim);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> tim;
    for (int i = 0; i < n; ++i) {
        cin >> board[i];
        for (int j = 0; j < n; ++j)
            if (board[i][j] == 'Z') start_r = i, start_c = j;
    }
    getline(cin, board[n]);
    getline(cin, board[n]);
    for (int i = 0; i < n; ++i) cin >> target[i];
    make_dist();
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (board[i][j] >= '0' && board[i][j] <= '9') {
                if (dist[i][j] == 0) dist[i][j] = tim;
                for (int t = 0; t < dist[i][j]; ++t)
                    id[i][j][t] = ++cnt;
            }
            if (target[i][j] >= '1' && target[i][j] <= '9')
                id[i][j][dist[i][j]] = ++cnt;
        }
    }
    int INF = 1e9;
    int S = 0, TT = cnt + 3;
    Dinic din(cnt + 5, S, TT);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (board[i][j] >= '1' && board[i][j] <= '9')
                din.add_edge(S, id[i][j][0], board[i][j] - '0');
            for (int d = 0; d < 4; ++d) {
                int nr = i + dr[d];
                int nc = j + dc[d];
                if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
                if (board[nr][nc] == 'Y' || board[nr][nc] == 'Z') continue;
                for (int t = 0;; ++t) {
                    if (id[i][j][t] == 0) break;
                    if (t == dist[i][j] && target[i][j] >= '1' && target[i][j] <= '9') break;
                    if (id[nr][nc][t + 1])
                        din.add_edge(id[i][j][t], id[nr][nc][t + 1], INF);
                }
            }
            if (target[i][j] >= '1' && target[i][j] <= '9') {
                for (int t = 0; t < dist[i][j]; ++t)
                    din.add_edge(id[i][j][t], id[i][j][t + 1], INF);
                din.add_edge(id[i][j][dist[i][j]], TT, target[i][j] - '0');
            }
        }
    }
    cout << din.max_flow() << '\n';
    return 0;
}
